/* ---------------------------------------------------------------------
   DATOS EN VIVO · USGS
   --------------------------------------------------------------------- */
/* =========================================================
   DATOS EN VIVO · USGS Earthquake Catalog (GeoJSON)
   - all_day: se consulta cada minuto (los sismos nuevos despiertan a la bestia)
   - 2.5_week: se consulta cada 5 minutos (mapas, cifras y barras)
   Solo se cuentan eventos de tipo "earthquake": el catálogo también
   registra explosiones, voladuras y sismos de hielo.
   ========================================================= */
(function(){
  const FEED_DIA = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson';
  const FEED_SEMANA = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson';
  const CADA_DIA = 60 * 1000, CADA_SEMANA = 5 * 60 * 1000;
  const MX = { latMin:14, latMax:33, lonMin:-118, lonMax:-86 };

  const escuchas = {};
  const vistos = new Set();
  const estado = { dia:[], semana:[], ultimaActualizacion:null, error:null, listo:false };

  function emitir(evento, dato){ (escuchas[evento]||[]).forEach(fn => { try{ fn(dato); }catch(e){ console.error(e); } }); }

  function limpiar(f){
    const p = f.properties || {}, c = (f.geometry && f.geometry.coordinates) || [0,0,0];
    return { id:f.id, mag: (typeof p.mag === 'number') ? p.mag : 0, lugar: p.place || 'Lugar sin nombre',
             hora: p.time, lon:c[0], lat:c[1], prof: (typeof c[2] === 'number') ? c[2] : 10,
             tipo: p.type || 'earthquake', url: p.url };
  }
  const esSismo = s => s.tipo === 'earthquake';

  async function pedir(url){
    const r = await fetch(url, { cache:'no-store' });
    if (!r.ok) throw new Error('USGS respondió ' + r.status);
    const j = await r.json();
    return (j.features || []).map(limpiar).filter(esSismo).sort((a,b) => b.hora - a.hora);
  }

  async function actualizarDia(){
    try{
      const lista = await pedir(FEED_DIA);
      const nuevos = [];
      lista.forEach(s => { if (!vistos.has(s.id)) { if (estado.listo) nuevos.push(s); vistos.add(s.id); } });
      estado.dia = lista;
      estado.ultimaActualizacion = new Date();
      estado.error = null;
      // Los sismos que llegan a all_day también deben aparecer en la semana (si son ≥ 2.5)
      nuevos.filter(s => s.mag >= 2.5).forEach(s => { if (!estado.semana.find(x => x.id === s.id)) estado.semana.unshift(s); });
      emitir('actualizado', estado);
      if (nuevos.length) emitir('nuevos', nuevos.sort((a,b) => a.hora - b.hora));
    }catch(e){ estado.error = e.message; emitir('error', e); }
  }

  async function actualizarSemana(){
    try{
      estado.semana = await pedir(FEED_SEMANA);
      estado.semana.forEach(s => vistos.add(s.id));
      emitir('actualizado', estado);
    }catch(e){ estado.error = e.message; emitir('error', e); }
  }

  async function iniciar(){
    await Promise.all([actualizarSemana(), actualizarDia()]);
    estado.listo = true;
    emitir('listo', estado);
    setInterval(actualizarDia, CADA_DIA);
    setInterval(actualizarSemana, CADA_SEMANA);
  }

  const enMexico = s => s.lat >= MX.latMin && s.lat <= MX.latMax && s.lon >= MX.lonMin && s.lon <= MX.lonMax;

  // Traducción mínima de los lugares de USGS ("45 km SW of Pinotepa, Mexico")
  const RUMBOS = {N:'N',S:'S',E:'E',W:'O',NE:'NE',NW:'NO',SE:'SE',SW:'SO',NNE:'NNE',NNW:'NNO',SSE:'SSE',SSW:'SSO',ENE:'ENE',ESE:'ESE',WNW:'ONO',WSW:'OSO'};
  function lugarES(t){
    if (!t) return 'Lugar sin nombre';
    let s = t.replace(/^(\d+)\s*km\s+([NSEW]{1,3})\s+of\s+/i, (_, km, r) => km + ' km al ' + (RUMBOS[r.toUpperCase()] || r) + ' de ');
    return s.replace(/\bMexico\b/g, 'México').replace(/\bregion\b/gi, 'región');
  }
  function hace(ms){
    const m = Math.round((Date.now() - ms) / 60000);
    if (m < 1) return 'hace un momento';
    if (m < 60) return 'hace ' + m + ' min';
    const h = Math.floor(m / 60);
    if (h < 24) return 'hace ' + h + ' h ' + (m % 60) + ' min';
    const d = Math.floor(h / 24); return 'hace ' + d + (d === 1 ? ' día' : ' días');
  }
  const horaLocal = ms => new Date(ms).toLocaleTimeString('es-MX', { hour:'2-digit', minute:'2-digit' });

  window.Datos = { estado, iniciar, enMexico, lugarES, hace, horaLocal, MX, refrescar: actualizarDia,
    on(evento, fn){ (escuchas[evento] = escuchas[evento] || []).push(fn); } };
})();

